// Loopback transport experiment, separate server and 200-socket client process.
// Native little-endian fixed layout is intentional for this single-host lab.
// Not an Internet protocol: authentication, encryption, congestion control absent.
#pragma pack(push,1)
struct InputPacket{uint32_t magic=0x494e5054,seq=0;uint16_t id=0;int16_t x=0,y=0;uint16_t reserved=0;};
struct PlayerRecord{int16_t x,y,z;uint16_t yaw;float hp;uint16_t attack,flags;};
struct BoltRecord{int16_t x,y,z;}; // 1 mm quantization, bounded [-32.768,32.767] m
struct PacketHeader{uint32_t magic=0x53544154,tick=0;uint16_t chunk=0,chunks=0,bytes=0,reserved=0;uint64_t checksum=0;};
#pragma pack(pop)
static_assert(sizeof(PlayerRecord)==16);
uint64_t hashBytes(const char*p,size_t n){uint64_t h=1469598103934665603ULL;for(size_t i=0;i<n;i++){h^=(uint8_t)p[i];h*=1099511628211ULL;}return h;}
void socketFail(const char*what){std::cerr<<what<<": "<<WSAGetLastError()<<"\n";std::exit(3);}
SOCKET udpSocket(int port=0){SOCKET s=socket(AF_INET,SOCK_DGRAM,IPPROTO_UDP);if(s==INVALID_SOCKET)socketFail("socket");sockaddr_in a{};a.sin_family=AF_INET;a.sin_addr.s_addr=htonl(INADDR_LOOPBACK);a.sin_port=htons(port);if(bind(s,(sockaddr*)&a,sizeof(a)))socketFail("bind");u_long nb=1;ioctlsocket(s,FIONBIO,&nb);int size=4*1024*1024;setsockopt(s,SOL_SOCKET,SO_RCVBUF,(char*)&size,sizeof(size));return s;}
void startSockets(){WSADATA d;if(WSAStartup(MAKEWORD(2,2),&d))socketFail("WSAStartup");}
constexpr int PAYLOAD=1152,STATE_BYTES=200*16+1000*6,CHUNKS=(STATE_BYTES+PAYLOAD-1)/PAYLOAD;
void preciseSleep(Clock::time_point deadline){
 static thread_local HANDLE timer=CreateWaitableTimerExW(nullptr,nullptr,0x00000002,TIMER_ALL_ACCESS);
 auto remaining=std::chrono::duration_cast<std::chrono::nanoseconds>(deadline-Clock::now()).count();if(remaining<=0)return;
 if(!timer){std::this_thread::sleep_until(deadline);return;}LARGE_INTEGER due;due.QuadPart=-std::max<int64_t>(1,remaining/100);SetWaitableTimer(timer,&due,0,nullptr,nullptr,FALSE);WaitForSingleObject(timer,INFINITE);
}
void networkServer(int ticks,int port){
 startSockets();SOCKET s=udpSocket(port);std::array<sockaddr_in,200> addr{};std::array<bool,200> registered{};std::array<uint32_t,200> seq{};int count=0;uint64_t inputs=0,stale=0,sendErrors=0,bytes=0,packets=0,unresolved=0;Fixture f(200,32,8,.70,true);f.networkInput=true;
 auto receive=[&](){for(;;){InputPacket in{};sockaddr_in from{};int len=sizeof(from);int n=recvfrom(s,(char*)&in,sizeof(in),0,(sockaddr*)&from,&len);if(n<0){if(WSAGetLastError()!=WSAEWOULDBLOCK)socketFail("recv input");break;}if(n!=sizeof(in)||in.magic!=0x494e5054||in.id>=200)continue;int i=in.id;if(!registered[i]){registered[i]=true;count++;addr[i]=from;}if(addr[i].sin_port!=from.sin_port)continue;if(in.seq<=seq[i]){stale++;continue;}seq[i]=in.seq;f.desired[i]={std::clamp(in.x/32767.,-1.,1.)*.5,std::clamp(in.y/32767.,-1.,1.)*.5,0};inputs++;}};
 auto wait=Clock::now();while(count<200&&millis(wait)<15000){receive();std::this_thread::sleep_for(std::chrono::milliseconds(1));}if(count!=200){std::cerr<<"Only "<<count<<" endpoints registered\n";std::exit(4);}
 std::vector<double> work,sim,send,interval,lateness;std::vector<char> state(STATE_BYTES);std::array<std::array<char,PAYLOAD+sizeof(PacketHeader)>,CHUNKS> wire{};auto start=Clock::now(),previous=start;int over=0;double pen=0;
 for(int tick=0;tick<ticks;tick++){
  auto deadline=start+std::chrono::duration_cast<Clock::duration>(std::chrono::duration<double>(tick*DT));preciseSleep(deadline);auto begin=Clock::now();lateness.push_back(std::max(0.,std::chrono::duration<double,std::milli>(begin-deadline).count()));if(tick)interval.push_back(std::chrono::duration<double,std::milli>(begin-previous).count());previous=begin;receive();auto b=Clock::now();f.crowd(tick);f.pose(tick);f.melee(tick);f.effects(tick);sim.push_back(millis(b));unresolved+=f.uncertain;pen=std::max(pen,f.lastPen);b=Clock::now();
  for(int i=0;i<200;i++){PlayerRecord r{(int16_t)std::lround(f.roots[i].x*1000),(int16_t)std::lround(f.roots[i].y*1000),0,(uint16_t)(i*73),float(f.hp[i]),(uint16_t)(tick/4),(uint16_t)(tick%4)};std::memcpy(state.data()+i*16,&r,sizeof(r));}
  for(int i=0;i<1000;i++){BoltRecord r{(int16_t)std::lround(f.bolts[i].x*1000),(int16_t)std::lround(f.bolts[i].y*1000),(int16_t)std::lround(f.bolts[i].z*1000)};std::memcpy(state.data()+3200+i*6,&r,sizeof(r));}
  for(int k=0;k<CHUNKS;k++){int n=std::min(PAYLOAD,STATE_BYTES-k*PAYLOAD);PacketHeader h;h.tick=tick;h.chunk=k;h.chunks=CHUNKS;h.bytes=n;h.checksum=hashBytes(state.data()+k*PAYLOAD,n);std::memcpy(wire[k].data(),&h,sizeof(h));std::memcpy(wire[k].data()+sizeof(h),state.data()+k*PAYLOAD,n);}
  // Identical observable state encoded once, still send separately to every peer.
  for(int i=0;i<200;i++)for(int k=0;k<CHUNKS;k++){int n=sizeof(PacketHeader)+std::min(PAYLOAD,STATE_BYTES-k*PAYLOAD);int sent=sendto(s,wire[k].data(),n,0,(sockaddr*)&addr[i],sizeof(addr[i]));if(sent!=n)sendErrors++;else{bytes+=n;packets++;}}
  send.push_back(millis(b));double ms=millis(begin);work.push_back(ms);if(ms>1000*DT)over++;
 }
 std::cout<<"{\"endpoints\":"<<count<<",\"ticks\":"<<ticks<<",\"state_bytes\":"<<STATE_BYTES<<",\"chunks\":"<<CHUNKS<<",\"inputs_applied\":"<<inputs<<",\"stale_inputs\":"<<stale<<",\"send_errors\":"<<sendErrors<<",\"packets\":"<<packets<<",\"udp_payload_bytes\":"<<bytes<<",\"work_over_budget\":"<<over<<",\"unresolved\":"<<unresolved<<",\"max_penetration_m\":"<<pen<<",\"elapsed_seconds\":"<<millis(start)/1000<<",";stats("tick_work_ms",work);std::cout<<",";stats("simulation_ms",sim);std::cout<<",";stats("encode_send_ms",send);std::cout<<",";stats("tick_start_interval_ms",interval);std::cout<<",";stats("start_lateness_ms",lateness);std::cout<<"}\n";closesocket(s);WSACleanup();if(sendErrors||unresolved)std::exit(2);
}
void networkClients(int ticks,int port){
 startSockets();std::array<SOCKET,200> sockets;for(auto&s:sockets)s=udpSocket();sockaddr_in server{};server.sin_family=AF_INET;server.sin_addr.s_addr=htonl(INADDR_LOOPBACK);server.sin_port=htons(port);std::atomic<bool> stop=false;std::atomic<uint64_t> received=0;uint64_t bad=0,duplicates=0,complete=0;std::vector<uint16_t> masks(size_t(200)*ticks);std::array<uint64_t,200> perPeer{};std::vector<uint32_t> latest(200);std::vector<double> assemblyDelay;std::vector<Clock::time_point> first(size_t(200)*ticks);auto begun=Clock::now();
 std::thread reader([&]{std::array<char,1500> buf;while(!stop){fd_set set;FD_ZERO(&set);for(auto s:sockets)FD_SET(s,&set);timeval timeout{0,5000};int n=select(0,&set,nullptr,nullptr,&timeout);if(n<0)socketFail("select");for(int i=0;i<200;i++)if(FD_ISSET(sockets[i],&set))for(;;){int got=recv(sockets[i],buf.data(),buf.size(),0);if(got<0){if(WSAGetLastError()!=WSAEWOULDBLOCK && WSAGetLastError()!=WSAECONNRESET)socketFail("recv state");break;}if(got<int(sizeof(PacketHeader))){bad++;continue;}PacketHeader h;std::memcpy(&h,buf.data(),sizeof(h));if(h.magic!=0x53544154||h.tick>=uint32_t(ticks)||h.chunk>=CHUNKS||h.chunks!=CHUNKS||h.bytes!=std::min(PAYLOAD,STATE_BYTES-int(h.chunk)*PAYLOAD)||got!=int(sizeof(h)+h.bytes)||h.checksum!=hashBytes(buf.data()+sizeof(h),h.bytes)){bad++;continue;}received++;perPeer[i]++;size_t slot=size_t(i)*ticks+h.tick;uint16_t bit=uint16_t(1u<<h.chunk);if(masks[slot]&bit){duplicates++;continue;}if(!masks[slot])first[slot]=Clock::now();masks[slot]|=bit;latest[i]=std::max(latest[i],h.tick);if(masks[slot]==uint16_t((1u<<CHUNKS)-1)){complete++;assemblyDelay.push_back(millis(first[slot]));}}}});
 uint32_t seq=1;auto deadline=Clock::now();while(millis(begun)<(ticks/30.+15)*1000){for(int i=0;i<200;i++){InputPacket p;p.id=i;p.seq=seq;p.x=(int16_t)(32767*std::sin(i*.7+seq*.04));p.y=(int16_t)(32767*std::cos(i*.3+seq*.03));if(sendto(sockets[i],(char*)&p,sizeof(p),0,(sockaddr*)&server,sizeof(server))!=sizeof(p))socketFail("send input");}seq++;if(received>=uint64_t(ticks)*200*CHUNKS)break;deadline+=std::chrono::duration_cast<Clock::duration>(std::chrono::duration<double>(DT));std::this_thread::sleep_until(deadline);}
 stop=true;reader.join();uint64_t expected=uint64_t(ticks)*200*CHUNKS;int peers=0;for(auto n:perPeer)if(n)peers++;std::cout<<"{\"endpoints_receiving\":"<<peers<<",\"expected_packets\":"<<expected<<",\"received_packets\":"<<received<<",\"missing_packets\":"<<(expected-received)<<",\"bad_packets\":"<<bad<<",\"duplicates\":"<<duplicates<<",\"complete_snapshots\":"<<complete<<",\"expected_snapshots\":"<<ticks*200<<",\"min_peer_packets\":"<<*std::min_element(perPeer.begin(),perPeer.end())<<",\"elapsed_seconds\":"<<millis(begun)/1000<<",";stats("chunk_assembly_ms",assemblyDelay);std::cout<<"}\n";for(auto s:sockets)closesocket(s);WSACleanup();if(bad||complete!=uint64_t(ticks)*200)std::exit(2);
}
